-- Captured source URLs and bytes are private; Firebase admins use a server-side proxy.
create table public.equipment_captured_images (
  id uuid primary key default gen_random_uuid(),
  equipment_id uuid not null references public.equipment(id) on delete cascade,
  source_url text not null check (source_url like 'https://oss-hk.247fitness.hk/%'),
  storage_path text unique,
  unique (equipment_id, source_url),
  check (storage_path is null or storage_path like equipment_id::text || '/' || id::text || '/%')
);
alter table public.equipment_captured_images enable row level security;
revoke all on public.equipment_captured_images from public, anon, authenticated;
grant select, insert, update, delete on public.equipment_captured_images to service_role;
-- No client RLS policies: Firebase authorization happens in the admin server route.
insert into storage.buckets(id, name, public, file_size_limit, allowed_mime_types)
values ('equipment-captured-images', 'equipment-captured-images', false, 20971520,
  array['image/jpeg','image/png','image/webp','image/gif'])
on conflict (id) do update set public = false;
-- Restrictive policy also blocks any existing permissive client Storage policies.
create policy captured_images_private on storage.objects as restrictive for all to anon, authenticated
using (bucket_id <> 'equipment-captured-images')
with check (bucket_id <> 'equipment-captured-images');

-- Seed from the committed captured catalog, never from display/official values.
-- Existing equipment identities only; leave review status and public images untouched.
